testcase.name:
test_plain_assignments_link_under_the_existing_contract[from pycircuit import module, rule
from .types import Word

@module
def Counter():
 state: Word = 254
 other: Word = 3

 @rule
 def tick():
 nonlocal state
 state = other

 tick()
-register copy]

test_plain_assignments_link_under_the_existing_contract[from pycircuit import module, rule
from .types import Word

@module
def Counter():
 state: Word = 254

 @rule
 def tick():
 nonlocal state
 state = 7

 tick()
-constant assignment]

