-one unused local assignment]

test_configured_llvm22_parses_private_source_transport[imports.py-from pycircuit import module, rule

@module
def Leaf():
 @rule
 def idle():
 return

 idle()
-None]

test_unsupported_source_forms_are_rejected_instead_of_silently_ignored[class DuplicateField:
 value: bool
 value: bool
 def __init__(self, value: bool):
 self.value = value
]

test_unsupported_source_forms_are_rejected_instead_of_silently_ignored[class DuplicateConstructor:
 value: bool
 def __init__(self, value: bool):
 self.value = value
 def __init__(self, value: bool):
 self.value = value
]

test_unsupported_source_forms_are_rejected_instead_of_silently_ignored[class VarArgs:
 value: bool
 def __init__(self, value: bool, *args):
 self.value = value
]

test_unsupported_source_forms_are_rejected_instead_of_silently_ignored[class VarKeywords:
 value: bool
 def __init__(self, value: bool, **kwargs):
 self.value = value
]

test_unsupported_source_forms_are_rejected_instead_of_silently_ignored[class ReceiverAnnotation:
 value: bool
 def __init__(self: ReceiverAnnotation, value: bool):
 self.value = value
]

test_unsupported_source_forms_are_rejected_instead_of_silently_ignored[class ReceiverDefault:
 value: bool
 def __init__(self=False, value: bool = True):
 self.value = value
]

